$ErrorActionPreference='SilentlyContinue'
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
[ComImport, Guid("BCDE0395-E52F-467C-8E3D-C4579291692E")] class MMDeviceEnumeratorComObject {}
[Guid("A95664D2-9614-4F35-A746-DE8DB63617E6"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
interface IMMDeviceEnumerator { int EnumAudioEndpoints(int f, int s, out IntPtr d); int GetDefaultAudioEndpoint(int f, int r, out IMMDevice d); }
[Guid("D666063F-1587-4E43-81F1-B948E807363F"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
interface IMMDevice { int Activate(ref Guid id, int ctx, IntPtr p, [MarshalAs(UnmanagedType.IUnknown)] out object o); }
[Guid("5CDF2C82-841E-4546-9722-0CF74078229A"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
interface IAudioEndpointVolume {
  int RegisterControlChangeNotify(IntPtr p); int UnregisterControlChangeNotify(IntPtr p); int GetChannelCount(out uint c);
  int SetMasterVolumeLevel(float l, ref Guid g); int SetMasterVolumeLevelScalar(float l, ref Guid g);
  int GetMasterVolumeLevel(out float l); int GetMasterVolumeLevelScalar(out float l);
  int SetChannelVolumeLevel(uint n, float l, ref Guid g); int SetChannelVolumeLevelScalar(uint n, float l, ref Guid g);
  int GetChannelVolumeLevel(uint n, out float l); int GetChannelVolumeLevelScalar(uint n, out float l);
  int SetMute([MarshalAs(UnmanagedType.Bool)] bool m, ref Guid g); int GetMute(out bool m);
}
public class Vol {
  static IAudioEndpointVolume Ep() {
    IMMDeviceEnumerator e = (IMMDeviceEnumerator)new MMDeviceEnumeratorComObject();
    IMMDevice d; e.GetDefaultAudioEndpoint(0, 1, out d);
    Guid g = typeof(IAudioEndpointVolume).GUID; object o; d.Activate(ref g, 23, IntPtr.Zero, out o);
    return (IAudioEndpointVolume)o;
  }
  public static int Get() { float v; Ep().GetMasterVolumeLevelScalar(out v); return (int)Math.Round(v * 100); }
  public static bool Muted() { bool m; Ep().GetMute(out m); return m; }
  public static void Set(int p) { Guid g = Guid.Empty; Ep().SetMasterVolumeLevelScalar(Math.Max(0, Math.Min(100, p)) / 100f, ref g); }
  public static void Mute(bool m) { Guid g = Guid.Empty; Ep().SetMute(m, ref g); }
}
'@
$ev=[System.Text.RegularExpressions.MatchEvaluator]{ param($m) ('\u{0:x4}' -f [int][char]$m.Value[0]) }
function Emit($t,$o){ $j=ConvertTo-Json -InputObject $o -Compress -Depth 4; $j=[regex]::Replace($j,'[^\x00-\x7F]',$ev); [Console]::WriteLine("$t $j") }
$self=''
while(($l=[Console]::In.ReadLine()) -ne $null){
  $x=$l.Trim() -split ' ',2; $arg=$x[1]
  try{
    switch($x[0]){
      'self' { $self=$arg }
      'vol' { Emit 'vol' @{ v=[Vol]::Get(); m=[Vol]::Muted() } }
      'setvol' { [Vol]::Set([int]$arg) }
      'mute' { [Vol]::Mute($arg -eq '1') }
      'wifi' {
        $ssid=''; $sig=0
        foreach($ln in @(netsh wlan show interfaces)){
          if($ln -match '^\s*SSID\s*:\s*(.+)$'){ $ssid=$Matches[1].Trim() }
          elseif($ln -match ':\s*(\d+)%'){ $sig=[int]$Matches[1] }
        }
        $nics=[Net.NetworkInformation.NetworkInterface]::GetAllNetworkInterfaces()
        $eth=[bool]($nics | Where-Object { $_.OperationalStatus -eq 'Up' -and $_.NetworkInterfaceType -eq 'Ethernet' })
        Emit 'wifi' @{ ssid=$ssid; sig=$sig; eth=$eth; up=[Net.NetworkInformation.NetworkInterface]::GetIsNetworkAvailable() }
      }
      'wifilist' {
        $known=@{}
        foreach($ln in @(netsh wlan show profiles)){ if($ln -match '^\s+\S.*?\s:\s(.+)$'){ $known[$Matches[1].Trim()]=$true } }
        $best=@{}; $cur=''
        foreach($ln in @(netsh wlan show networks mode=bssid)){
          if($ln -match '^\s*SSID\s+\d+\s*:\s*(.*)$'){ $cur=$Matches[1].Trim(); if($cur -and -not $best.ContainsKey($cur)){ $best[$cur]=0 } }
          elseif($cur -and $ln -match ':\s*(\d+)%'){ $v=[int]$Matches[1]; if($v -gt $best[$cur]){ $best[$cur]=$v } }
        }
        $r=@($best.Keys | ForEach-Object { [pscustomobject]@{ s=$_; g=$best[$_]; k=[bool]$known[$_] } } | Sort-Object g -Descending | Select-Object -First 12)
        Emit 'wifilist' $r
      }
      'wificonn' {
        $s=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($arg))
        netsh wlan connect name="$s" ssid="$s" | Out-Null
      }
      'bg' {
        $win=$env:windir
        $r=@(Get-Process | Where-Object { $_.MainWindowHandle -eq 0 -and $_.Path -and -not $_.Path.StartsWith($win,[StringComparison]::OrdinalIgnoreCase) -and $_.Path -ne $self -and $_.ProcessName -notmatch '^(powershell|pwsh|conhost|node|electron|WindowsTerminal|OpenConsole)$' } | Group-Object Path | ForEach-Object { [pscustomobject]@{ n=$_.Group[0].ProcessName; p=$_.Name } } | Sort-Object n | Select-Object -First 32)
        Emit 'bg' $r
      }
    }
  }catch{}
}

taskbar.ps1.data:
param([string]$a,[string]$par)
if($a -eq 'start'){
  Add-Type -AssemblyName System.Windows.Forms
  [System.Windows.Forms.SendKeys]::SendWait('^{ESC}')
  exit
}
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public class TB {
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int l, t, r, b; }
  [StructLayout(LayoutKind.Sequential)] public struct APPBARDATA { public int cbSize; public IntPtr hWnd; public uint uCallbackMessage; public uint uEdge; public RECT rc; public IntPtr lParam; }
  [DllImport("shell32.dll")] static extern IntPtr SHAppBarMessage(uint m, ref APPBARDATA d);
  [DllImport("user32.dll")] static extern IntPtr FindWindow(string c, string w);
  [DllImport("user32.dll")] static extern IntPtr FindWindowEx(IntPtr p, IntPtr a, string c, string w);
  [DllImport("user32.dll")] static extern bool ShowWindow(IntPtr h, int n);
  public static void Autohide(bool on) {
    APPBARDATA d = new APPBARDATA(); d.cbSize = Marshal.SizeOf(d);
    d.hWnd = FindWindow("Shell_TrayWnd", null);
    d.lParam = (IntPtr)(on ? 1 : 2);
    SHAppBarMessage(0xA, ref d);
  }
  public static void Tray(int n) {
    foreach (string c in new string[] { "Shell_TrayWnd", "Shell_SecondaryTrayWnd" }) {
      IntPtr h = IntPtr.Zero;
      while ((h = FindWindowEx(IntPtr.Zero, h, c, null)) != IntPtr.Zero) ShowWindow(h, n);
    }
  }
}
'@
if($a -eq 'hide'){
  [TB]::Autohide($true)
  $i = 0
  while($true){
    [TB]::Tray(0)
    Start-Sleep -Milliseconds 200
    $i++
    if($par -and ($i % 10 -eq 0) -and -not (Get-Process -Id ([int]$par) -ErrorAction SilentlyContinue)){ [TB]::Autohide($false); [TB]::Tray(5); exit }
  }
} else {
  [TB]::Autohide($false); [TB]::Tray(5)
}

windows.ps1.data:
param([string]$a,[string]$h,[string]$p)
$ErrorActionPreference='SilentlyContinue'
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
Add-Type -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.Text;
using System.Runtime.InteropServices;
public class WinInfo { public long h; public int pid; public string t; }
public class WN {
  delegate bool EnumProc(IntPtr h, IntPtr l);
  [DllImport("user32.dll")] static extern bool EnumWindows(EnumProc p, IntPtr l);
  [DllImport("user32.dll")] static extern int GetWindowTextLength(IntPtr h);
  [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern int GetWindowText(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] static extern IntPtr GetWindow(IntPtr h, uint c);
  [DllImport("user32.dll")] static extern int GetWindowLong(IntPtr h, int i);
  [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h);
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr h, int n);
  [DllImport("user32.dll")] public static extern bool IsIconic(IntPtr h);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out int pid);
  [DllImport("dwmapi.dll")] static extern int DwmGetWindowAttribute(IntPtr h, int a, out int v, int s);
  public static bool Cloaked(IntPtr h) { int v; DwmGetWindowAttribute(h, 14, out v, 4); return v != 0; }
  public static int FgPid() { int pid; GetWindowThreadProcessId(GetForegroundWindow(), out pid); return pid; }
  // toutes les fenêtres "de barre des tâches" (y compris plusieurs fenêtres d'un même processus, ex. l'Explorateur de fichiers)
  public static List<WinInfo> List() {
    List<WinInfo> r = new List<WinInfo>();
    EnumWindows(delegate(IntPtr h, IntPtr l) {
      if (!IsWindowVisible(h) || Cloaked(h)) return true;
      int len = GetWindowTextLength(h); if (len <= 0) return true;
      int ex = GetWindowLong(h, -20);
      bool tool = (ex & 0x80) != 0, app = (ex & 0x40000) != 0;
      if (tool && !app) return true;
      if (GetWindow(h, 4) != IntPtr.Zero && !app) return true;
      StringBuilder sb = new StringBuilder(len + 1); GetWindowText(h, sb, sb.Capacity);
      int pid; GetWindowThreadProcessId(h, out pid);
      WinInfo w = new WinInfo(); w.h = h.ToInt64(); w.pid = pid; w.t = sb.ToString(); r.Add(w);
      return true;
    }, IntPtr.Zero);
    return r;
  }
}
'@
if($a -eq 'focus'){
  $hw=[IntPtr][int64]$h
  if([WN]::IsIconic($hw)){[void][WN]::ShowWindow($hw,9)}
  if(-not [WN]::SetForegroundWindow($hw)){ (New-Object -ComObject WScript.Shell).AppActivate([int]$p) | Out-Null }
  exit
}
$cache=@{}; $last=''
while($true){
  try{
    if($cache.Count -gt 400){ $cache=@{} }
    $o=@([WN]::List() | ForEach-Object {
      $id=$_.pid
      if(-not $cache.ContainsKey($id)){
        $pr=Get-Process -Id $id -ErrorAction SilentlyContinue
        $cache[$id]=@{p=$pr.Path;n=$pr.ProcessName}
      }
      $c=$cache[$id]
      if($c.p){ [pscustomobject]@{pid=$id;h=$_.h;t=$_.t;p=$c.p;n=$c.n} }
    })
    $fp=[WN]::FgPid()
    $sig="$fp|"+((@($o|ForEach-Object{"$($_.h)"}) ) -join ',')
    # n'émet que lorsque quelque chose change (ouverture, fermeture, fenêtre active) : réactif sans spammer
    if($sig -ne $last){ $last=$sig; [Console]::WriteLine((@{fp=$fp;w=$o}|ConvertTo-Json -Compress -Depth 4)) }
  }catch{}
  Start-Sleep -Milliseconds 200
}

worker.ps1.data:
$ErrorActionPreference='SilentlyContinue'
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public class WK {
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h);
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr h, int n);
  [DllImport("user32.dll")] public static extern bool IsIconic(IntPtr h);
  [DllImport("user32.dll")] public static extern void keybd_event(byte vk, byte sc, uint fl, UIntPtr ex);
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int l, t, r, b; }
  [StructLayout(LayoutKind.Sequential)] public struct APPBARDATA { public int cbSize; public IntPtr hWnd; public uint uCallbackMessage; public uint uEdge; public RECT rc; public IntPtr lParam; }
  [DllImport("shell32.dll")] static extern IntPtr SHAppBarMessage(uint m, ref APPBARDATA d);
  [DllImport("user32.dll")] static extern IntPtr FindWindow(string c, string w);
  [DllImport("user32.dll")] static extern IntPtr FindWindowEx(IntPtr p, IntPtr a, string c, string w);
  static void Autohide(bool on) {
    APPBARDATA d = new APPBARDATA(); d.cbSize = Marshal.SizeOf(d);
    d.hWnd = FindWindow("Shell_TrayWnd", null);
    d.lParam = (IntPtr)(on ? 1 : 2);
    SHAppBarMessage(0xA, ref d);
  }
  static void Tray(int n) {
    foreach (string c in new string[] { "Shell_TrayWnd", "Shell_SecondaryTrayWnd" }) {
      IntPtr h = IntPtr.Zero;
      while ((h = FindWindowEx(IntPtr.Zero, h, c, null)) != IntPtr.Zero) ShowWindow(h, n);
    }
  }
  // la barre Windows est re-masquée en continu par un timer natif (explorer la réaffiche au survol du bord bas)
  static System.Threading.Timer tm;
  public static void Hide() { Autohide(true); Tray(0); if (tm == null) tm = new System.Threading.Timer(delegate(object o) { Tray(0); }, null, 120, 120); }
  public static void Show() { if (tm != null) { tm.Dispose(); tm = null; } Autohide(false); Tray(5); }
  public static void Tap(byte vk) { keybd_event(vk, 0, 0, UIntPtr.Zero); keybd_event(vk, 0, 2, UIntPtr.Zero); }
}
'@
# processus persistant : évite de relancer PowerShell (~0,5 s) à chaque clic
while(($l=[Console]::In.ReadLine()) -ne $null){
  $x=$l.Trim() -split ' '
  switch($x[0]){
    'start' { [WK]::Tap(0x5B) }
    'hide' { [WK]::Hide() }
    'show' { [WK]::Show() }
    'focus' {
      $hw=[IntPtr][int64]$x[1]
      if([WK]::IsIconic($hw)){[void][WK]::ShowWindow($hw,9)}
      if(-not [WK]::SetForegroundWindow($hw)){
        [WK]::Tap(0x12)
        if(-not [WK]::SetForegroundWindow($hw)){ (New-Object -ComObject WScript.Shell).AppActivate([int]$x[2]) | Out-Null }
      }
    }
  }
}
# le parent est mort (stdin fermé) : on rend la barre Windows
[WK]::Show()
